param([Parameter(Mandatory=$true)][string]$RepoRoot,[string]$SourceRoot,[string]$Out)
. "$PSScriptRoot\_vcvars.ps1";$vcDir=Get-VcVarsDir
$ErrorActionPreference='Stop';$RepoRoot=[IO.Path]::GetFullPath((Resolve-Path -LiteralPath $RepoRoot).Path);if(-not$SourceRoot){$SourceRoot=$RepoRoot};$SourceRoot=[IO.Path]::GetFullPath((Resolve-Path -LiteralPath $SourceRoot).Path);$SourceDir=Join-Path $SourceRoot 'src'
if(-not$Out){$Out=Join-Path $RepoRoot ('_scratch/pad_census_alias/run_'+[guid]::NewGuid().ToString('N'))};$Out=[IO.Path]::GetFullPath($Out);if(Test-Path -LiteralPath $Out){throw 'Fresh output required'};if(-not$Out.StartsWith($RepoRoot+'\',[StringComparison]::OrdinalIgnoreCase)){throw 'Private root output required'};[void][IO.Directory]::CreateDirectory($Out)
$model=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../test/vi_pad_census_alias_memory.cpp'))
& python "$PSScriptRoot/vi_pad_census_alias_extract.py" --source-dir $SourceDir --root $SourceRoot --out "$Out/actual";if($LASTEXITCODE-ne0){throw 'source extraction failed'};$sourcepins=Get-Content -LiteralPath "$Out/actual/sourcepins.json" -Raw|ConvertFrom-Json;$fixtureHash=(Get-FileHash -LiteralPath $model).Hash;$rows=@()
foreach($arch in @('x64','x86')){$folder=Join-Path $Out $arch;[void][IO.Directory]::CreateDirectory("$folder/temp");$vc=if($arch-eq'x64'){'vcvars64.bat'}else{'vcvars32.bat'};@('@echo off',('call "'+$vcDir+'\'+$vc+'" >nul || exit /b 2'),('set "TEMP='+$folder+'\temp"'),('set "TMP='+$folder+'\temp"'),('cl /nologo /O2 /EHsc /std:c++17 /W4 /WX /I"'+$Out+'\actual" /Fo"'+$folder+'\model.obj" /Fe"'+$folder+'\model.exe" "'+$model+'" /link /OPT:NOICF >"'+$folder+'\build.log" 2>&1'),'exit /b %errorlevel%')|Set-Content -LiteralPath "$folder/build.cmd" -Encoding ascii;& cmd /d /c "$folder/build.cmd";$compile=$LASTEXITCODE;$code=$null;$result=$null;if($compile-eq0){& "$folder/model.exe" >"$folder/run.log";$code=$LASTEXITCODE;try{$result=Get-Content -LiteralPath "$folder/run.log" -Tail 1|ConvertFrom-Json}catch{}};$row=@{arch=$arch;compile_exit=$compile;run_exit=$code;result=$result;build_log="$folder/build.log"};$rows+=,$row;$row|ConvertTo-Json -Compress -Depth 5}
$stable=(Get-FileHash -LiteralPath $model).Hash-eq$fixtureHash;foreach($p in $sourcepins.inputs.PSObject.Properties){if((Get-FileHash -LiteralPath $p.Name).Hash-ne$p.Value){$stable=$false}};$pass=0;$fail=0;foreach($r in $rows){if($r.result){$pass+=$r.result.passed;$fail+=$r.result.failed}};$complete=$stable-and@($rows|Where-Object {$_.compile_exit-ne0-or$_.result.completed-ne$true}).Count-eq0;@{completed=$complete;source_stable=$stable;passed=$pass;failed=$fail;cases=$rows;fixture_sha256=$fixtureHash;scope='finite fake callbacks only; no real aliases or controller/native API execution; no expected-red inversion'}|ConvertTo-Json -Depth 7|Set-Content -LiteralPath "$Out/result.json" -Encoding utf8;Write-Output "RESULT $Out";if(-not$complete-or$fail-or@($rows|Where-Object run_exit -ne 0).Count){exit 1}
